// ============================================================
// FILE: build-deliverable.js
// SYSTEM: 30DayBrand Client Delivery
// TYPE: Styling engine (executable JavaScript — RUN, not parsed as a prompt)
// STATUS: Production
// PURPOSE: Renders deliverable DOCX files with canonical 30DayBrand styling
//          (magenta #FF00FF accent, charcoal #1A1A1A headings, Roboto). Consumes
//          TEMPLATE_A/B/C and the generator output specs.
// GUARDRAIL: n/a (code, not a prompt)
// CANONICAL SOURCE: "30DayBrand — Business" master project. Edit there, not in client copies.
// VERSION: current   UPDATED: 2026-05-29
// ============================================================

// Reusable 30DayBrand deliverable DOCX builder.
// Locked design: title + "what this is" + Before You Start box + checklist + numbered Step blocks
// (What to do / Copy this box / Done when) + Need Help footer.
const fs = require('fs');
const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, HeadingLevel, BorderStyle, WidthType, ShadingType, ExternalHyperlink,
  Header, Footer, ImageRun, PageNumber, TabStopType, TabStopPosition
} = require('docx');

// Logo baked in as base64 so the builder is fully self-contained (no external PNG dependency).
// Override by setting LOGO_PATH to an external file if you ever swap the logo.
const LOGO_B64 = "";

const BRAND = "C2008F";      // tuned magenta (legible on white, for text accents)
const MAGENTA = "FF00FF";    // pure brand magenta — sparing: top bar, logo, small accents
const HEAD = "1A1A1A";       // charcoal for headings (readability; magenta headings vibrate)
const COPYBG = "F2F4F7";     // light grey for copy boxes
const PREBG  = "FFF4E5";     // soft amber for "before you start"
const CHKBG  = "EAF1FB";     // light blue for checklist

function t(text, opts={}) { return new TextRun({ text, ...opts }); }

function para(children, opts={}) {
  if (typeof children === 'string') children = [t(children)];
  return new Paragraph({ children, spacing: { after: 120 }, ...opts });
}

function h1(text){ return new Paragraph({ heading: HeadingLevel.HEADING_1, spacing:{after:160}, children:[t(text,{bold:true,color:HEAD,size:36})] }); }
function h2(text){ return new Paragraph({ heading: HeadingLevel.HEADING_2, spacing:{before:240,after:120}, children:[t(text,{bold:true,color:MAGENTA,size:28})] }); }

// shaded single-cell box
// Content width: US Letter 12240 - 2×1440 margins = 9360 DXA
const CONTENT_WIDTH_DXA = 9360;
function box(children, fill) {
  return new Table({
    width: { size: CONTENT_WIDTH_DXA, type: WidthType.DXA },
    columnWidths: [ CONTENT_WIDTH_DXA ],
    borders: {
      top:{style:BorderStyle.SINGLE,size:6,color:"D0D5DD"}, bottom:{style:BorderStyle.SINGLE,size:6,color:"D0D5DD"},
      left:{style:BorderStyle.SINGLE,size:6,color:"D0D5DD"}, right:{style:BorderStyle.SINGLE,size:6,color:"D0D5DD"},
    },
    rows: [ new TableRow({ children: [ new TableCell({
      width: { size: CONTENT_WIDTH_DXA, type: WidthType.DXA },
      shading: { type: ShadingType.CLEAR, fill },
      margins: { top:120, bottom:120, left:160, right:160 },
      children
    }) ] }) ]
  });
}

function copyBox(lines) {
  // lines: array of strings (paragraphs) to be copied verbatim
  const kids = [ para([t("Copy this:", {bold:true, size:20, color:"475467"})], {spacing:{after:60}}) ];
  lines.forEach((ln,i) => kids.push(new Paragraph({ spacing:{after: i===lines.length-1?0:80}, children:[t(ln,{font:"Roboto Mono", size:20})] })));
  return box(kids, COPYBG);
}

function step(num, title, whatToDo, copyLines, doneWhen, extraNotes) {
  const out = [];
  out.push(new Paragraph({ spacing:{before:220, after:60}, children:[ t(`Action ${num} — ${title}`, {bold:true, size:26, color:"101828"}) ]}));
  if (whatToDo) out.push(para([t("What to do: ",{bold:true}), t(whatToDo)]));
  (extraNotes||[]).forEach(n => out.push(para([t("Note: ",{italics:true,bold:true}), t(n,{italics:true})])));
  if (copyLines && copyLines.length) out.push(copyBox(copyLines));
  if (doneWhen) out.push(para([t("✅ Done when: ",{bold:true,color:"067647"}), t(doneWhen)], {spacing:{before:80, after:60}}));
  return out;
}

function checklist(items){
  const kids=[ para([t("Your checklist",{bold:true,size:22,color:MAGENTA})],{spacing:{after:80}}) ];
  items.forEach(it=> kids.push(new Paragraph({spacing:{after:40}, children:[t("☐  ",{size:22}), t(it,{size:22})]})));
  return box(kids, CHKBG);
}

function beforeBox(items){
  const kids=[ para([t("Before you start",{bold:true,size:22,color:"B54708"})],{spacing:{after:80}}) ];
  items.forEach(it=> kids.push(new Paragraph({spacing:{after:40}, children:[t("•  ",{size:22}), t(it,{size:22})]})));
  return box(kids, PREBG);
}

function helpFooter(videoUrl, bonusUrl){
  const HELP = "https://30daybrand.com/client-help";
  const kids=[ para([t("Need help?",{bold:true,size:22,color:MAGENTA})],{spacing:{after:80}}) ];
  kids.push(new Paragraph({spacing:{after:40},children:[t("Watch the setup video for this section on our Get Help page: "), new ExternalHyperlink({link:HELP, children:[t(HELP,{style:"Hyperlink",color:"1155CC",underline:{}})]})]}));
  kids.push(new Paragraph({spacing:{after:40},children:[t("Still stuck after the video? On that same page there's a button to book a 15-minute setup call with us. Or bring your question to your session — your 30DayBrand guide will help you live.")]}));
  return box(kids, COPYBG);
}

// ---- shared document shell (logo header + magenta footer) ----
// Owns the page-1 logo and the every-page footer so build() and buildOnePager()
// produce byte-for-byte identical brand treatment. Do not inline this in either
// function — both must call it so A/B/C deliverables and the 1-pagers match exactly.
function makeShellElements(spec){
  const clientName = spec.clientName || "[CLIENT NAME]";

  // Logo data: external file if LOGO_PATH set, otherwise the baked-in base64 (self-contained default).
  let logoData;
  try {
    if (process.env.LOGO_PATH && fs.existsSync(process.env.LOGO_PATH)) {
      logoData = fs.readFileSync(process.env.LOGO_PATH);
    } else {
      logoData = Buffer.from(LOGO_B64, "base64");
    }
  } catch(e) { logoData = null; }

  // First-page-only header: logo 90px, top-left, aligned to body left margin
  let firstHeader;
  try {
    if (logoData) {
      firstHeader = new Header({ children:[ new Paragraph({ spacing:{before:0,after:0},
        children:[ new ImageRun({ data: logoData, type:"png", transformation:{ width:90, height:81 } }) ] }) ] });
    }
  } catch(e) { firstHeader = undefined; }

  // Every-page footer: thin magenta bar + footer line (left brand / center client / right page)
  const footerBar = new Table({
    width:{size:CONTENT_WIDTH_DXA,type:WidthType.DXA},
    columnWidths:[ CONTENT_WIDTH_DXA ],
    borders:{top:{style:BorderStyle.NONE},bottom:{style:BorderStyle.NONE},left:{style:BorderStyle.NONE},right:{style:BorderStyle.NONE}},
    rows:[ new TableRow({ children:[ new TableCell({ width:{size:CONTENT_WIDTH_DXA,type:WidthType.DXA}, shading:{type:ShadingType.CLEAR,fill:MAGENTA},
      children:[ new Paragraph({spacing:{after:0},children:[t("",{size:2})]}) ] }) ] }) ]
  });
  const footerLine = new Paragraph({
    spacing:{before:80,after:0},
    tabStops:[ {type:TabStopType.CENTER, position:4680}, {type:TabStopType.RIGHT, position:9360} ],
    children:[
      t("30DayBrand.com", {size:16, color:"98A2B3"}),
      t("\tPrepared exclusively for "+clientName, {size:16, color:"98A2B3"}),
      t("\tPage ", {size:16, color:"98A2B3"}),
      new TextRun({ children:[ PageNumber.CURRENT ], size:16, color:"98A2B3" }),
    ]
  });
  const everyFooter = new Footer({ children:[ footerBar, footerLine ] });

  return { firstHeader, everyFooter };
}

// ---- assemble a document from a spec object ----
function build(spec, outPath){
  const { firstHeader, everyFooter } = makeShellElements(spec);

  const children = [];
  children.push(new Paragraph({spacing:{before:60,after:0},children:[]})); // small gap under header zone
  children.push(h1(spec.title));
  if(spec.whatThisIs) children.push(para([t(spec.whatThisIs,{size:22})]));
  children.push(new Paragraph({spacing:{after:80}, children:[t("This document includes:",{bold:true})]}));
  spec.includes.forEach(i=> children.push(new Paragraph({bullet:{level:0}, children:[t(i)]})));
  children.push(new Paragraph({spacing:{before:120,after:80}, children:[]}));
  children.push(beforeBox(spec.before));
  children.push(new Paragraph({spacing:{after:80},children:[]}));
  children.push(checklist(spec.checklist));
  // sections + steps
  (spec.sections||[]).forEach(sec=>{
    children.push(h2(sec.heading));
    if(sec.intro) children.push(para([t(sec.intro,{italics:true})]));
    (sec.steps||[]).forEach(s=> step(s.n,s.title,s.do,s.copy,s.done,s.notes).forEach(p=>children.push(p)));
    (sec.rawCopy||[]).forEach(block=>{ children.push(copyBox(block)); });
  });
  children.push(new Paragraph({spacing:{before:160,after:80},children:[]}));
  children.push(helpFooter(spec.videoUrl, spec.bonusUrl));

  const doc = new Document({
    styles:{ default:{ document:{ run:{ font:"Roboto", size:22 } } } },
    sections:[{
      properties:{
        titlePage: true,
        page:{ size:{width:12240,height:15840}, margin:{ top:1440, right:1440, bottom:1440, left:1440, header:720, footer:560 } }
      },
      headers:{ first: firstHeader || new Header({children:[new Paragraph({children:[]})]}),
                default: new Header({children:[new Paragraph({children:[]})]}) },
      footers:{ first: everyFooter, default: everyFooter },
      children
    }]
  });
  return Packer.toBuffer(doc).then(buf=> fs.writeFileSync(outPath, buf));
}

// ---- 1-pager body helpers ----
// highlightBox: the "In one line" callout near the top of a 1-pager (charcoal label + content).
function highlightBox(label, lines){
  const arr = Array.isArray(lines) ? lines : [lines];
  const kids = [ para([t(label, {bold:true, size:22, color:HEAD})], {spacing:{after:60}}) ];
  arr.forEach((ln,i)=> kids.push(new Paragraph({ spacing:{after: i===arr.length-1?0:60}, children:[t(ln,{size:22})] })));
  return box(kids, COPYBG);
}

// closingBox: the guarantee / belief box at the end of a 1-pager. Magenta-tinted label, sparing accent.
function closingBox(label, lines){
  const arr = Array.isArray(lines) ? lines : [lines];
  const kids = [ para([t(label, {bold:true, size:22, color:MAGENTA})], {spacing:{after:60}}) ];
  arr.forEach((ln,i)=> kids.push(new Paragraph({ spacing:{after: i===arr.length-1?0:60}, children:[t(ln,{size:22})] })));
  return box(kids, COPYBG);
}

// proseSection: a content section for a 1-pager — heading + prose paragraphs and/or bullets.
// Block shapes: {p:"text"} => paragraph; {b:["a","b"]} => bullet list; {lead:"Label:", p:"text"} => bold lead-in run + text.
function proseBlocks(blocks){
  const out = [];
  (blocks||[]).forEach(bl=>{
    if (bl.b) { bl.b.forEach(it=> out.push(new Paragraph({bullet:{level:0}, spacing:{after:60}, children:[t(it,{size:22})]}))); return; }
    if (bl.lead) { out.push(para([t(bl.lead+" ",{bold:true,size:22}), t(bl.p||"",{size:22})])); return; }
    out.push(para([t(bl.p||"",{size:22})]));
  });
  return out;
}

// ---- assemble a 1-pager (quick-reference card) from a spec object ----
// Skeleton: title + one-line subtitle + "In one line" highlight box + prose content sections
//           + a guarantee/belief closing box. No checklist, no Step blocks, no copy boxes.
// Shares the SAME brand constants, baked-in page-1 logo, and per-page footer as build().
function buildOnePager(spec, outPath){
  const { firstHeader, everyFooter } = makeShellElements(spec);

  const children = [];
  children.push(new Paragraph({spacing:{before:60,after:0},children:[]})); // small gap under header zone
  children.push(h1(spec.title));
  if (spec.subtitle) children.push(new Paragraph({ spacing:{after:160}, children:[t(spec.subtitle,{italics:true, size:20, color:"475467"})] }));
  if (spec.oneLine) children.push(highlightBox(spec.oneLineLabel || "In one line", spec.oneLine));

  (spec.sections||[]).forEach(sec=>{
    children.push(h2(sec.heading));
    if (sec.intro) children.push(para([t(sec.intro,{italics:true})]));
    proseBlocks(sec.blocks).forEach(p=> children.push(p));
  });

  if (spec.closing) {
    children.push(new Paragraph({spacing:{before:120,after:80},children:[]}));
    children.push(closingBox(spec.closing.label || "The guarantee", spec.closing.lines));
  }

  const doc = new Document({
    styles:{ default:{ document:{ run:{ font:"Roboto", size:22 } } } },
    sections:[{
      properties:{
        titlePage: true,
        page:{ size:{width:12240,height:15840}, margin:{ top:1440, right:1440, bottom:1440, left:1440, header:720, footer:560 } }
      },
      headers:{ first: firstHeader || new Header({children:[new Paragraph({children:[]})]}),
                default: new Header({children:[new Paragraph({children:[]})]}) },
      footers:{ first: everyFooter, default: everyFooter },
      children
    }]
  });
  return Packer.toBuffer(doc).then(buf=> fs.writeFileSync(outPath, buf));
}

module.exports = { build, buildOnePager };
